type Status = enum { Open, Paid }

fn code(s: Status) -> Int {
    match s {
        Status { .. } => 1    // ✗ `Status` is an enum, not a record
        _ => 2
    }
}

fn code(s: Status) -> Int {
    match s {
        Open => 1             // ✓ name the variants
        Paid => 2
    }
}
